<script setup lang="ts">
const route = useRoute(); const { resources, findResource } = useResources(); const article = findResource(String(route.params.slug))
if (!article) throw createError({ statusCode: 404, statusMessage: 'Resource not found' })
useSeoPage(article.title, article.description, `/resources/${article.slug}`)
const related = resources.filter(item => item.slug !== article.slug && item.category === article.category).slice(0, 2)
</script>
